import React, { useState } from 'react';
import { Box, Drawer, AppBar, Toolbar, IconButton, Typography, InputBase, Avatar, Badge, List, ListItemButton, ListItemIcon, ListItemText, Divider, Tooltip, CssBaseline, Stack, Chip } from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import SearchIcon from '@mui/icons-material/Search';
import NotificationsNoneIcon from '@mui/icons-material/NotificationsNone';
import DashboardRoundedIcon from '@mui/icons-material/DashboardRounded';
import BarChartRoundedIcon from '@mui/icons-material/BarChartRounded';
import BiotechRoundedIcon from '@mui/icons-material/BiotechRounded';
import LocalFireDepartmentRoundedIcon from '@mui/icons-material/LocalFireDepartmentRounded';
import PsychologyRoundedIcon from '@mui/icons-material/PsychologyRounded';
import InsightsRoundedIcon from '@mui/icons-material/InsightsRounded';
import DescriptionRoundedIcon from '@mui/icons-material/DescriptionRounded';
import SettingsRoundedIcon from '@mui/icons-material/SettingsRounded';
import { motion } from 'framer-motion';
import { useLocation, Link } from 'react-router-dom';

const drawerWidth = 260;
const menuItems = [
  { label: 'Dashboard', icon: <DashboardRoundedIcon />, path: '/' },
  { label: 'Quality Analytics', icon: <BarChartRoundedIcon />, path: '/quality-analytics' },
  { label: 'Flaky Tests', icon: <BiotechRoundedIcon />, path: '/flaky-tests' },
  { label: 'Hotspots', icon: <LocalFireDepartmentRoundedIcon />, path: '/hotspots' },
  { label: 'AI Root Cause', icon: <PsychologyRoundedIcon />, path: '/root-cause' },
  { label: 'Failure Trends', icon: <InsightsRoundedIcon />, path: '/failure-trends' },
  { label: 'Weekly Digest', icon: <DescriptionRoundedIcon />, path: '/weekly-digest' },
  { label: 'Settings', icon: <SettingsRoundedIcon />, path: '/settings' },
];

function DashboardShell({ children }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const theme = useTheme();
  const location = useLocation();

  const handleDrawerToggle = () => setMobileOpen(!mobileOpen);

  const drawer = (
    <Box sx={{ height: '100%', bgcolor: 'rgba(15,23,42,0.96)', borderRight: '1px solid rgba(148,163,184,0.14)' }}>
      <Box sx={{ p: 3, display: 'flex', alignItems: 'center', gap: 1.5 }}>
        <Box sx={{ width: 42, height: 42, borderRadius: 2, bgcolor: 'linear-gradient(135deg, #2563EB, #0EA5E9)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 700 }}>IT</Box>
        <Box>
          <Typography variant="subtitle1" fontWeight={700}>Intelligent Test</Typography>
          <Typography variant="caption" color="text.secondary">Insights Engine</Typography>
        </Box>
      </Box>
      <Divider sx={{ borderColor: 'rgba(148,163,184,0.14)' }} />
      <List sx={{ px: 1.5, py: 1.5 }}>
        {menuItems.map((item) => {
          const active = location.pathname === item.path;
          return (
            <ListItemButton
              key={item.label}
              component={Link}
              to={item.path}
              selected={active}
              sx={{
                borderRadius: 2,
                mb: 0.75,
                color: active ? 'white' : 'text.secondary',
                bgcolor: active ? 'rgba(37,99,235,0.18)' : 'transparent',
                '&.Mui-selected': { bgcolor: 'rgba(37,99,235,0.24)', color: 'white' },
                '&:hover': { bgcolor: 'rgba(148,163,184,0.12)' },
              }}
            >
              <ListItemIcon sx={{ color: active ? '#60A5FA' : 'inherit', minWidth: 36 }}>{item.icon}</ListItemIcon>
              <ListItemText primary={item.label} />
            </ListItemButton>
          );
        })}
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: '#020617' }}>
      <CssBaseline />
      <AppBar position="fixed" elevation={0} sx={{ width: { md: `calc(100% - ${drawerWidth}px)` }, ml: { md: `${drawerWidth}px` }, bgcolor: 'rgba(2,6,23,0.7)', backdropFilter: 'blur(18px)', borderBottom: '1px solid rgba(148,163,184,0.14)' }}>
        <Toolbar sx={{ gap: 1.5 }}>
          <IconButton color="inherit" edge="start" sx={{ mr: 2, display: { md: 'none' } }} onClick={handleDrawerToggle} aria-label="Open sidebar">
            <MenuIcon />
          </IconButton>
          <Box sx={{ flexGrow: 1, display: 'flex', alignItems: 'center', gap: 1.5, bgcolor: 'rgba(30,41,59,0.75)', border: '1px solid rgba(148,163,184,0.16)', borderRadius: 999, px: 2, py: 1 }}>
            <SearchIcon color="action" />
            <InputBase placeholder="Search insights, modules, tests" sx={{ color: 'white', width: '100%' }} inputProps={{ 'aria-label': 'Search insights' }} />
          </Box>
          <Stack direction="row" alignItems="center" spacing={1}>
            <Tooltip title="Notifications"><IconButton color="inherit" aria-label="Notifications"><Badge badgeContent={4} color="error"><NotificationsNoneIcon /></Badge></IconButton></Tooltip>
            <Avatar sx={{ bgcolor: '#2563EB', width: 36, height: 36 }}>AD</Avatar>
            <Chip label="Enterprise" color="primary" size="small" />
          </Stack>
        </Toolbar>
      </AppBar>
      <Box component="nav" sx={{ width: { md: drawerWidth }, flexShrink: { md: 0 } }}>
        <Drawer variant="temporary" open={mobileOpen} onClose={handleDrawerToggle} ModalProps={{ keepMounted: true }} sx={{ display: { xs: 'block', md: 'none' }, '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth } }}>
          {drawer}
        </Drawer>
        <Drawer variant="permanent" open sx={{ display: { xs: 'none', md: 'block' }, '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth } }}>
          {drawer}
        </Drawer>
      </Box>
      <Box component="main" sx={{ flexGrow: 1, p: { xs: 2, md: 3 }, pt: { xs: 10, md: 12 } }}>
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35 }}>
          {children}
        </motion.div>
      </Box>
    </Box>
  );
}

export default DashboardShell;
